from ..enums import Ability, DamageClass, MoveTarget


class MoveChecks:
    """Move validation and checking methods."""

    def check_executable(self, attacker, defender, battle):
        """Check if the move can be executed."""
        if self.effect == 60 and attacker.truant_turn % 2:
            return "But it failed!\n"
        if self.effect == 86:
            if not attacker.confusion.active():
                return "But it failed!\n"
        if self.effect == 118:
            if attacker.hp >= attacker.starting_hp:
                return "But it failed!\n"
        if self.effect == 219:
            if attacker.attack_stage <= -6:
                return "But it failed!\n"
        if self.effect == 220:
            if attacker.spatk_stage <= -6:
                return "But it failed!\n"
        if self.effect == 221:
            if attacker.defense_stage <= -6:
                return "But it failed!\n"
        if self.effect == 222:
            if attacker.spdef_stage <= -6:
                return "But it failed!\n"
        if self.effect == 223:
            if attacker.speed_stage <= -6:
                return "But it failed!\n"
        if self.effect == 253:
            if not attacker.infatuated:
                return "But it failed!\n"
        if self.effect == 279:
            if not attacker.nv.sleep():
                return "But it failed!\n"
        if self.effect == 281:
            if not defender.nv.sleep():
                return "But it failed!\n"
        return ""

    def check_semi_invulnerable(self, attacker, defender, battle):
        """Check semi-invulnerable states."""
        msg = ""
        if attacker.dive and self.id != 414:
            msg += "But it failed!\n"
        if attacker.dig and self.id != 414:
            msg += "But it failed!\n"
        if attacker.fly and self.id != 414:
            msg += "But it failed!\n"
        if attacker.shadow_force and self.id != 414:
            msg += "But it failed!\n"
        return msg

    def check_protect(self, attacker, defender, battle):
        """Check protect-related moves."""
        if self.effect == 182:
            if defender.protect.active():
                return "But it failed!\n"
        if self.effect == 201:
            if defender.protect.active():
                return "But it failed!\n"
        if self.effect == 269:
            if defender.protect.active():
                return "But it failed!\n"
        if self.effect == 270:
            if defender.protect.active():
                return "But it failed!\n"
        return ""

    def check_hit(self, attacker, defender, battle):
        """Check if move hits."""
        if self.accuracy:
            accuracy = attacker.get_accuracy()
            evasion = defender.get_evasion()
            hit_chance = self.accuracy * (accuracy / evasion)
            if hit_chance >= 100 or self.accuracy == 0:
                pass
            else:
                if random.randint(0, 99) >= hit_chance:
                    return "But it missed!\n"

        if self.target in (MoveTarget.SELECTED_POKEMON, MoveTarget.RANDOM_OPPONENT):
            pass

        return ""

    def check_effective(self, attacker, defender, battle, current_type):
        """Check move effectiveness."""
        effectiveness = defender.effectiveness(current_type, battle, attacker=attacker, move=self)
        if effectiveness <= 0:
            return "But it had no effect!\n"
        if effectiveness < 1:
            return "It's not very effective...\n"
        if effectiveness > 1:
            return "It's super effective!\n"
        return ""


