        return self.damage_class != DamageClass.STATUS and self.id not in [210, 214, 226, 241, 242, 243, 249, 250, 251, 282, 310, 311, 313, 314, 343, 347, 469, 486, 493, 496, 503, 515, 531, 548, 549, 560, 588, 614, 639, 641, 690, 711]

